def calculate_s_and_t(N):
    """Computes S(N) and T(N) for a given N."""

    # Calculate S(N)
    S_N = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // N_plus_1

    # Calculate T(N)
    # Note: We should check if T(N) is an integer, as the problem suggests the sum is equal to this value.
    # Since we are comparing it to an integer sum S(N), T(N) must be an integer.
    T_N_num = N**3 - N**2 + 2

    if T_N_num % 4 != 0:
        T_N = T_N_num / 4
    else:
        T_N = T_N_num / 4

    return S_N, T_N

results = {}
for N in range(1, 11):
    S_N, T_N = calculate_s_and_t(N)
    results[N] = (S_N, T_N)

for N, (S_N, T_N) in results.items():
    print(f"N={N}: S(N)={S_N}, T(N)={T_N}")

def calculate_S(N):
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // (N + 1)
    return S_N

def calculate_T(N):
    # T(N) = (N^3 - N^2 + 2) / 4
    # Since S(N) is an integer, T(N) must be an integer for a match to occur.
    # We check for this property first.
    numerator = N**3 - N**2 + 2
    if numerator % 4 != 0:
        # Return a value that clearly indicates it's not an integer match
        return None
    return numerator / 4

results = []
for N in range(1, 51):
    S_N = calculate_S(N)
    T_N_float = calculate_T(N)

    match = False
    if T_N_float is not None:
        # T(N) is an integer
        T_N_int = int(T_N_float)
        if S_N == T_N_int:
            match = True
        else:
            match = False
    else:
        # T(N) is not an integer, so it cannot match S(N)
        match = False

    results.append({
        'N': N,
        'S(N)': S_N,
        'T(N)': T_N_float if T_N_float is not None else None,
        'Match': match
    })

# Print results in a format suitable for writing to notes
print("N | S(N) | T(N) | Match")
for res in results:
    t_display = f"{res['T(N)']:.1f}" if res['T(N)'] is not None else "X.X"
    match_str = "YES" if res['Match'] else "NO"
    print(f"{res['N']:<2} | {res['S(N)']:<4} | {t_display:<4} | {match_str}")
